export type Platform = 'macos' | 'windows' | 'linux';

export interface Discount {
  enabled: boolean;
  platforms: Platform[];
}



export interface PaymentOffer {
  id: string;
  name: string;
  html: string[];
  css: string[];
  js: string[];
  assets: string[];
  start_time: string; // unix seconds, as a string
  end_time: string;   // unix seconds, as a string
  platforms: Platform[];
  discount: Discount;
}

export interface CountryConfig {
  location: 'world' | (string & {}); // "world", "US", or other country codes
  language: string[];                // "en", "en_us", "en_uk", ...
  payload: PaymentOffer[][];         // array of offer groups
}

export interface PaymentCampaignResponse {
  "getPayment" : boolean,
  'api-global-version': string;
  'api-version': string;
  'app-version-range': [string, string]; // [min, max]
  country: CountryConfig[];
}

export interface PaymentJsonReturnType {
  latestConfig : PaymentCampaignResponse,
  location : string | null
  
}






